def decide(observation, tools):
    match_scores = tools.match()
    frame = 1 if match_scores[1] > match_scores[0] else 0
    view = observation["views"][frame]
    heading = view["heading"]
    point_result = tools.point()
    if point_result[0] is None and point_result[1] is None:
        return frame, "right" if heading > 0 else "left", {"heading": heading}
    point = point_result[1 - (heading > 0)]  # pick point from frame with matching heading sign
    if point is None:
        return frame, "right" if heading > 0 else "left", {"heading": heading}
    x, y = point
    # Estimate lateral shift based on heading and known right_of_end_m
    old_right = view["right_of_end_m"]
    if old_right == 0:
        return frame, "right" if heading > 0 else "left", {"heading": heading}
    # Assume object is directly ahead; lateral offset is old_right + d
    # d = x * (forward range estimate) but we lack range
    # Use only heading direction for turn decision
    return frame, "right" if heading > 0 else "left", {"heading": heading}

